async def act(page):
    import asyncio
    from pathlib import Path

    # Save path for exported CSV
    download_path = Path("/tmp/magento_canceled_orders.csv")

    # Step 1: navigate to Sales > Orders grid (deterministic relative goto)
    await page.goto('/index.php/admin/sales_order/')
    await page.wait_for_load_state('networkidle')

    # Step 2: attempt to set the Status filter to 'Canceled' by scanning comboboxes
    status_set = False
    try:
        comboboxes = page.get_by_role('combobox')
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            # Attempt selection by visible label first
            try:
                await cb.select_option(label='Canceled')
                status_set = True
                break
            except Exception:
                # try likely value fallback
                try:
                    await cb.select_option(value='canceled')
                    status_set = True
                    break
                except Exception:
                    # not this combobox
                    continue
    except Exception:
        status_set = False

    # Step 3: Click the Search / Filter button to apply the filter (if present)
    try:
        search_btn = page.get_by_role('button', name=lambda n: n and 'search' in n.lower())
        if await search_btn.count() > 0:
            await search_btn.first.click()
        else:
            # fallback: a button-like control whose name contains 'filter' or 'search'
            fallback_btn = page.get_by_role('button', name=lambda n: n and ('filter' in n.lower() or 'search' in n.lower()))
            if await fallback_btn.count() > 0:
                await fallback_btn.first.click()
    except Exception:
        # proceed; grid may auto-refresh
        pass

    # Allow grid to refresh
    await asyncio.sleep(1)

    # Step 4: locate an export combobox (native <select> exposed as role='combobox') that contains a CSV option
    export_select = None
    try:
        comboboxes = page.get_by_role('combobox')
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            try:
                opts = await cb.get_by_role('option').all_inner_texts()
            except Exception:
                opts = []
            chosen_label = None
            for opt in opts:
                if opt and 'csv' in opt.lower():
                    chosen_label = opt
                    break
            if chosen_label:
                try:
                    await cb.select_option(label=chosen_label)
                    export_select = cb
                    break
                except Exception:
                    # try selecting by value fallback
                    try:
                        # attempt to find the option value by checking each option element
                        option_locators = cb.get_by_role('option')
                        opt_count = await option_locators.count()
                        val_to_try = None
                        for j in range(opt_count):
                            o = option_locators.nth(j)
                            try:
                                text = await o.inner_text()
                                if text and 'csv' in text.lower():
                                    val_to_try = await o.get_attribute('value')
                                    break
                            except Exception:
                                continue
                        if val_to_try:
                            await cb.select_option(value=val_to_try)
                            export_select = cb
                            break
                    except Exception:
                        continue
    except Exception:
        export_select = None

    # Step 5: locate Export button and trigger download
    if export_select is not None:
        try:
            export_btn = page.get_by_role('button', name=lambda n: n and 'export' in n.lower())
            if await export_btn.count() > 0:
                export_button = export_btn.first
            else:
                # try other button-like elements with 'export' in their accessible name
                alt = page.get_by_role('button').filter(has_text=lambda t: 'export' in (t or '').lower()) if hasattr(page.get_by_role('button'), 'filter') else None
                export_button = alt.first if alt and await alt.count() > 0 else None

            if export_button:
                async with page.expect_download() as dl_info:
                    await export_button.click()
                download = await dl_info.value
                await download.save_as(str(download_path))
        except Exception:
            # give it one more try after short wait
            try:
                await asyncio.sleep(1)
                export_btn = page.get_by_role('button', name=lambda n: n and 'export' in n.lower())
                if await export_btn.count() > 0:
                    async with page.expect_download(timeout=10000) as dl_info:
                        await export_btn.first.click()
                    download = await dl_info.value
                    await download.save_as(str(download_path))
            except Exception:
                # export failed
                pass

    # Step 6: If we have a saved CSV, print it exactly as retrieved so downstream steps can analyze it
    if download_path.exists():
        try:
            b = download_path.read_bytes()
            try:
                csv_text = b.decode('utf-8')
            except Exception:
                csv_text = b.decode('latin-1', errors='replace')
            # Print the CSV exactly as retrieved
            print(csv_text)
        except Exception as e:
            print(f"ERROR_READING_DOWNLOAD: {e}")
    else:
        # Fallback: capture the visible orders table text and print it for analysis
        try:
            tables = page.get_by_role('table')
            tab_count = await tables.count()
            dumped = []
            for i in range(tab_count):
                t = tables.nth(i)
                try:
                    text = await t.inner_text()
                    text = text.replace('\u00a0', ' ')
                    dumped.append(text)
                except Exception:
                    continue
            if dumped:
                for d in dumped:
                    print(d)
            else:
                print('ERROR: Could not export CSV or capture table snapshot.')
        except Exception:
            print('ERROR: Could not export CSV or capture table snapshot.')

